<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { ResizeContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: ResizeContract  = $props();
const open=control(()=>p.open,untrack(()=>p.defaultOpen),false,open=>p.onOpenChange?.({open}));const value=control(()=>p.value,untrack(()=>p.defaultValue),'100',value=>p.onValueChange?.({value}));const uid=$props.id();const levels=$derived(p.levels??[90,100,110,130,150].map(percent=>({id:String(percent),label:`${percent}%`,percent})));let root:HTMLDivElement;let trigger:HTMLButtonElement;async function choose(id:string){value.request(id);open.request(false);await tick();if(!open.value)trigger?.focus();}function key(e:KeyboardEvent){if(ignoredKey(e))return;if(e.key==='Escape'&&open.value){e.preventDefault();open.request(false);void tick().then(()=>{if(!open.value)trigger?.focus();});}if(!open.value&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const i=levels.findIndex(x=>x.id===value.value),next=levels[i+(e.key==='ArrowDown'?1:-1)];if(next)value.request(next.id);}}onMount(()=>{const outside=(e:PointerEvent)=>{if(!root.contains(e.target as Node))open.request(false);};document.addEventListener('pointerdown',outside);return()=>document.removeEventListener('pointerdown',outside);});
</script>
<div bind:this={root} {...owned('resize','root',open.value?'open':'closed')} onkeydown={key}><button bind:this={trigger} type="button" aria-expanded={open.value} aria-controls={uid} {...owned('resize','trigger',open.value?'open':'closed')} onclick={()=>open.request(!open.value)}>화면 크기 {levels.find(x=>x.id===value.value)?.label}</button><ul hidden={!open.value} id={uid} {...owned('resize','list',open.value?'open':'closed')}>{#each levels as level(level.id)}<li><button type="button" aria-pressed={value.value===level.id} {...owned('resize','option',value.value===level.id&&'selected')} onclick={()=>choose(level.id)}>{level.label}</button></li>{/each}</ul></div>
